// Images embedded in the daily log email, taken from the Outlook template it replaces.
// Base64 so the server route carries them in its own bundle (public/ files are not
// traced into Vercel functions). Server-side only: never import this from a client
// component, it would add ~85 KB to the page.

export interface EmailImage {
  cid: string
  filename: string
  contentType: string
  width: number
  height: number
  alt: string
  base64: string
}

/** "East Midlands Route · Network Readiness Statement" banner at the top of the email. */
export const BANNER: EmailImage = {
  cid: 'emcc-banner',
  filename: 'emcc-banner.png',
  contentType: 'image/png',
  width: 693,
  height: 141,
  alt: 'East Midlands Route - Network Readiness Statement',
  base64: '',
}

/** East Midlands route strip under the signature. */
export const SIGNATURE: EmailImage = {
  cid: 'em-signature',
  filename: 'em-signature.jpg',
  contentType: 'image/jpeg',
  width: 418,
  height: 98,
  alt: 'East Midlands - Putting our passengers and freight customers first',
  base64: '',
}
